import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class NonPokemonBatch60Test {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final List<String> IDS=List.of("sm12_en_206");
    static final String TAG="sm10_en_001",SUP="sm12_en_189",CN="sc_csm2cc_182_sr",NORMAL="sm11-5_en_058";
    static final TrainerProfile PROFILE=NonPokemonBatch2Test.DATA.trainer(IDS.getFirst()).orElseThrow();
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static CardInstance hand(ServerMatch m,UUID p,String id){return DynamicPassiveModifierTest.hand(m,p,id);}
    public static void main(String[] args){identities();search();System.out.println("NonPokemonBatch60Test passed: TAG TEAM Pokemon and all six Supporter identities with archived CN printings; unrelated two-person Supporter excluded; both owners, zero/one/two picks and duplicate names, private search/public reveal, exact hand transfer and mandatory shuffle");}
    static void identities(){var spec=ZoneSelectionEffect.from(PROFILE.effectProgram().triggers().getFirst().effects().getFirst());var db=BundledRules.loadCardDefinitions();for(var c:db.all())if(c.pokemonFamilies().contains(PokemonFamily.TAG_TEAM))check(spec.allows(c),"Omitted TAG TEAM Pokemon "+c.id());for(String id:List.of("sm12_en_186","sm12_en_189","sm12_en_193","sm12_en_198","sm12_en_199","sm12_en_202","sm12_en_228","sm12_en_229","sm12_en_231","sm12_en_234","sc_csm2cc_182_sr","sc_csm2ac_185_sr","sc_csm2bc_179_sr","sc_csm2bc_186_sr","sc_csm2_5c_079_sr"))check(spec.allows(def(id,false)),"Omitted TAG TEAM Supporter "+id);check(!spec.allows(def(NORMAL,false))&&!spec.allows(def("trainer",false)),"Non-TAG TEAM two-person Supporter or Item admitted");}
    static CardDefinition def(String id,boolean pokemon){return new CardDefinition(id,id,pokemon?CardCategory.POKEMON:CardCategory.TRAINER,pokemon?TrainerCategory.NONE:id.equals("trainer")?TrainerCategory.ITEM:TrainerCategory.SUPPORTER,"H",Set.of("international"),pokemon,false,60,Map.of(),EffectSupport.SUPPORTED,null);}
    static ServerMatch aiGame(String id){return fixture();}
    static ServerMatch fixture(){var defs=new ArrayList<CardDefinition>();var profiles=new HashMap<String,PokemonProfile>();var trainers=new HashMap<String,TrainerProfile>();String[] pattern={"basic","basic","basic",TAG,TAG,SUP,CN,NORMAL,"trainer","trainer"};for(String key:Arrays.stream(pattern).distinct().toList()){boolean pokemon=key.equals("basic")||key.equals(TAG);defs.add(def(key,pokemon));if(pokemon)profiles.put(key,new PokemonProfile(500,0,null,null,0,null,0,1,List.of(GeneratedRuleBatch8Test.hit(100,false)),List.of(),EnergyType.COLORLESS));else trainers.put(key,key.equals("trainer")?PROFILE:DeckDiscardTriggeredAbilityTest.trainer("SUPPORTER","{\"type\":\"draw\",\"amount\":1}"));}var combat=new CombatCatalog(profiles,Map.of(),trainers);
        for(int seed=0;seed<500;seed++){var decks=new ArrayList<List<CardInstance>>();for(UUID p:List.of(A,B)){var deck=new ArrayList<CardInstance>();for(int i=0;i<60;i++)deck.add(new CardInstance(new UUID(p.getLeastSignificantBits(),i+1),p,pattern[i%pattern.length]));decks.add(deck);}var m=new ServerMatch(A,B,decks.get(0),decks.get(1),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),combat,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);if(List.of(A,B).stream().anyMatch(p->m.privateView(p).hand().stream().filter(c->m.cardDefinition(c.definitionId()).basicPokemon()).count()<2))continue;OpeningTestSupport.complete(m,A,B,1);m.drawCardsByEffect(A,A,15);m.drawCardsByEffect(A,B,15);m.endTurn(A);m.endTurn(B);if(List.of(A,B).stream().allMatch(p->m.privateView(p).hand().stream().anyMatch(c->c.definitionId().equals("trainer"))&&List.of(TAG,SUP,CN,NORMAL).stream().allMatch(k->m.privateView(p).deck().stream().filter(c->c.definitionId().equals(k)).count()>=(k.equals(TAG)?2:1))))return m;}throw new AssertionError("No Tag Call fixture");}
    static void search(){for(UUID p:List.of(A,B))for(List<String> names:List.of(List.<String>of(),List.of(TAG),List.of(SUP),List.of(CN),List.of(TAG,SUP),List.of(SUP,CN),List.of(TAG,TAG))){var m=fixture();if(p.equals(B))m.endTurn(A);UUID other=p.equals(A)?B:A;var source=hand(m,p,"trainer");int before=m.privateView(p).hand().size(),rng=m.randomTranscript().size();var opp=m.privateView(other).hand();m.playTrainer(p,source.instanceId(),null);var q=m.effectCardPrompt(p);check(q.minimum()==0&&q.maximum()==2&&q.candidates().stream().allMatch(c->Set.of(TAG,SUP,CN).contains(c.definitionId())),"Wrong TAG TEAM search scope");GeneratedRuleBatch8Test.reject(()->m.effectCardPrompt(other));var selected=new ArrayList<CardInstance>();for(String name:names)selected.add(q.candidates().stream().filter(c->c.definitionId().equals(name)&&!selected.contains(c)).findFirst().orElseThrow());var wrong=m.privateView(p).deck().stream().filter(c->c.definitionId().equals(NORMAL)).findFirst().orElseThrow();GeneratedRuleBatch8Test.reject(()->m.submitEffectCards(p,q.resolutionId(),q.step(),List.of(wrong.instanceId())));m.submitEffectCards(p,q.resolutionId(),q.step(),selected.stream().map(CardInstance::instanceId).toList());if(!selected.isEmpty()){var reveal=m.effectCardReveal();check(reveal!=null&&reveal.cardIds().stream().sorted().toList().equals(selected.stream().map(CardInstance::definitionId).sorted().toList()),"Chosen cards were not publicly revealed");m.acknowledgeEffectReveal(reveal.confirmingPlayer(),reveal.id());}NonPokemonBatch2Test.settle(m);check(m.privateView(p).hand().size()==before-1+selected.size()&&m.privateView(p).hand().containsAll(selected)&&m.privateView(p).discard().contains(source)&&m.privateView(other).hand().equals(opp),"Wrong search transfer/owner");check(m.randomTranscript().size()>rng,"Tag Call omitted shuffle after search/decline");}}
}
